trait Speak {
    fn name(&self) -> String;
    fn sound(&self) -> String;

    // default method: built from the required ones
    fn intro(&self) -> String {
        format!("{} says {}", self.name(), self.sound())
    }
}

struct Dog {
    name: String,
}

struct Robot {
    id: u32,
}

impl Speak for Dog {
    fn name(&self) -> String {
        self.name.clone()
    }
    fn sound(&self) -> String {
        String::from("woof")
    }
}

impl Speak for Robot {
    fn name(&self) -> String {
        format!("Robot {}", self.id)
    }
    fn sound(&self) -> String {
        String::from("beep")
    }
    // override the default
    fn intro(&self) -> String {
        format!("[{}] {}", self.name(), self.sound())
    }
}

fn main() {
    let dog = Dog { name: String::from("Rex") };
    let robot = Robot { id: 7 };
    println!("{}", dog.intro());
    println!("{}", robot.intro());
}

use std::fmt;

struct Point {
    x: i32,
    y: i32,
}

impl fmt::Display for Point {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "({}, {})", self.x, self.y)
    }
}

fn main() {
    let p = Point { x: 3, y: -1 };
    println!("point is {p}");
    let text = p.to_string();   // free, because Point implements Display
    println!("{} bytes", text.len());
}

