trait Speak {
    fn speak(&self) -> String;

    fn shout(&self) -> String {
        self.speak().to_uppercase()
    }
}

struct Dog {
    name: String,
}

struct Robot {
    id: u32,
}

impl Speak for Dog {
    fn speak(&self) -> String {
        format!("woof, I am {}", self.name)
    }
}

impl Speak for Robot {
    fn speak(&self) -> String {
        format!("beep {}", self.id)
    }
}

fn main() {
    let dog = Dog { name: String::from("Rex") };
    println!("{}", dog.shout());
    let robot = Robot { id: 7 };
    println!("{}", robot.shout());
}
